/* ===== Writer C — Chapter 3: Winter, The Cannery (weeks 25-36) ===== */
const c3At=(w,d,s)=>()=>S.week===w&&S.day===d&&S.slot===s;
const c3S=(z,e,p,m)=>say('',t(z,e,p),m);
function c3_trustAll(n){Object.keys(S.npc).forEach(k=>{if(S.npc[k].met&&k!=='travis')addTrust(k,n)})}
function c3_send(n){S.cash-=n;S.flags.sentMoney=(S.flags.sentMoney||0)+n;S.flags.c3_mom='money';
 log(`寄回家 $${n}`,`Sent $${n} home`,`Enviaste $${n} para casa`)}
const c3_ok=(id,n)=>rel(id).met&&rel(id).trust>=n;
const c3_lic=()=>S.flags.license===true;
const c3_prepared=()=>!!((S.flags.c3_prep&&S.flags.c3_prep!=='none')||S.flags.c3_gate||S.flags.c3_map||S.flags.c3_gap);

/* --- mother's illness: shared choice list --- */
function c3_momChoices(){return [
 {t:t('寄 $500 回家','Send $500 home','Mandar $500 para casa'),req:MONEY(500),fx:()=>{c3_send(500);stat('saud',4)}},
 {t:t('寄 $1,500 回家','Send $1,500 home','Mandar $1.500 para casa'),req:MONEY(1500),fx:()=>{c3_send(1500);stat('saud',2);S.rep-=1},
  next:()=>c3S('账户一下空了。医药费全付清了。','Your account empties in one go. The hospital bill is paid in full.','A conta fica vazia de uma vez. A conta do hospital fica paga.')},
 {t:t('每晚视频陪她','Video-call her every night','Fazer-lhe videochamada todas as noites'),fx:()=>{S.flags.c3_mom='video';stat('saud',10);S.lusoThisWeek=true;S.restBonus=(S.restBonus||0)-2},
  next:()=>c3S('你每晚十点打过去，里斯本是凌晨四点，她总醒着。你们不说病，只说楼下谁家又吵架了。','You call every night at ten. It\'s 4 a.m. in Lisbon and she\'s always awake. You don\'t talk about being sick, only about which neighbors are fighting again.','Ligas todas as noites às dez. Em Lisboa são quatro da manhã e ela está sempre acordada. Não falam da doença, só de que vizinhos voltaram a discutir.')},
 {t:t('请格蕾丝想办法','Ask Grace to find a way','Pedir à Grace uma solução'),req:()=>rel('grace').trust>=4||NEED(t('格蕾丝信任 4','Grace trust 4','Confiança da Grace 4')),
  fx:()=>{S.flags.sentMoney=(S.flags.sentMoney||0)+1200;S.flags.c3_mom='grace';addTrust('grace',2);log('若泽的信托寄给母亲 $1,200','José\'s trust sent your mother $1,200','O fundo do José enviou $1.200 à tua mãe')},
  next:()=>c3S('格蕾丝翻了一夜档案：若泽在信托里留了 $1,200，备注只有一行——“给费尔南达，如果她需要。”他一分没动过。','Grace searches the files all night. José left $1,200 in the trust with a one-line note: "For Fernanda, if she ever needs it." He never touched a cent.','A Grace passa a noite nos processos. O José deixou $1.200 no fundo, com uma nota: «Para a Fernanda, se algum dia precisar.» Nunca lhe tocou.')}
]}
function c3_graceWill(){return {title:t('格蕾丝的办公室','Grace\'s office','O escritório da Grace'),meta:t('遗嘱第四条','Clause four','Cláusula quarta'),text:[
 t('格蕾丝把遗嘱翻到第四条，一字一字念：“受益人须亲自经营该店，连续四十八周，其间离开圣鲁伊斯不得超过三日。”','Grace turns to clause four and reads it word by word: "The beneficiary shall personally operate the business for forty-eight consecutive weeks and not be absent from San Luís more than three days."','A Grace abre o testamento na cláusula quarta e lê palavra a palavra: «O beneficiário gerirá pessoalmente o negócio durante quarenta e oito semanas consecutivas, sem se ausentar de San Luís mais de três dias.»'),
 t('“走一周，遗嘱作废，店和地归县里拍卖。我们都知道谁会来竞拍。”','"Leave for a week and the will is void. Shop and land go to county auction. We both know who\'ll bid."','«Uma semana fora e o testamento caduca. Restaurante e terreno vão a leilão. Sabemos os dois quem vai licitar.»')],
 choices:[{t:t('不管了，还是回去','Go home anyway','Voltar na mesma'),next:()=>({title:t('妈妈的声音','Your mother\'s voice','A voz da tua mãe'),meta:t('里斯本','Lisbon','Lisboa'),text:[
   t('你开始收拾箱子。手机又响了，是妈妈，声音很弱：“你舅舅等了二十年才等到有人去那个店。你敢为了我丢掉它，我就不认你。寄点钱，每天打个电话，就够了。”','You start packing. The phone rings — Mom, her voice thin. "Your uncle waited twenty years for someone to go to that shop. Throw it away for me and you\'re no son of mine. Send a little money, call every day. That\'s enough."','Começas a fazer a mala. O telemóvel toca — é a mãe, com a voz fraca. «O teu tio esperou vinte anos que alguém fosse para aquele restaurante. Se o deitas fora por mim, deixas de ser meu filho. Manda um dinheirinho, liga todos os dias. Chega.»')],choices:c3_momChoices()})},
  ...c3_momChoices()]};
}

/* --- finale helpers --- */
function c3_search(who){
 const intro={
  beto:t('贝托的皮卡来了，副驾驶上一把猎枪盖着毯子。“1998 年我死了十一头牛。今晚我要看看是谁欠我的。”','Beto\'s pickup rolls up, a shotgun under a blanket on the seat. "Lost eleven head in \'98. Tonight I want to see who owes me."','Chega a carrinha do Beto, com uma caçadeira tapada no banco. «Em 98 morreram-me onze cabeças. Hoje quero ver quem me deve.»'),
  lucia:t('露西娅拎着一袋狗粮来了：“厂里有群野狗。它们认得我。”','Lucía shows up with a bag of dog food. "There\'s a pack of strays in there. They know me."','A Lucía aparece com um saco de ração. «Há uma matilha lá dentro. Conhecem-me.»'),
  wade:t('韦德一句话没说，把你的手电调成红光：“守夜的看不见红光。”','Wade says nothing, just switches your flashlight to red. "Watchman can\'t see red."','O Wade não diz nada, só põe a tua lanterna em vermelho. «O guarda não vê o vermelho.»'),
  roz:t('罗兹在铁轨边看表：“十点十分。守夜的刚巡完，我们有四十分钟。”','Roz checks her watch by the tracks. "Ten past ten. Watchman just did his round. We\'ve got forty minutes."','A Roz olha para o relógio junto à linha. «Dez e dez. O guarda acabou a ronda. Temos quarenta minutos.»'),
  alone:t('你一个人沿着铁轨走。远处州际公路上的卡车声像潮水。','You walk the tracks alone. The trucks on the interstate sound like the tide.','Vais sozinho pela linha. Os camiões na autoestrada soam como a maré.')}[who];
 const ch=[];
 ch.push({t:t('[用枪] 把枪拔出来','[Gun] Draw the gun','[Arma] Sacar da arma'),req:()=>S.course.gun>=1||NEED(t('用枪课 1/3','Shooting 1/3','Tiro 1/3')),next:()=>c3_outcome(who,S.course.gun>=2?'shot':'shaky')});
 ch.push({t:t('关掉手电，屏住呼吸','Kill the light, hold your breath','Apagar a lanterna e suster a respiração'),next:()=>c3_outcome(who,'hide')});
 if(who!=='alone')ch.push({t:t('交给同伴','Leave it to your companion','Deixar com quem vem contigo'),next:()=>c3_outcome(who,'friend')});
 return {title:t('二号仓库后面','Behind Warehouse Two','Atrás do Armazém Dois'),meta:t('第三章 · 章末','Chapter 3 · Finale','Capítulo 3 · Final'),text:[intro,
  t('更衣室的门半塌着，鱼腥和铁锈味二十多年没散。十七号柜在最里面。这时仓库那头传来低沉的狗叫，一道手电光扫过窗户。','The locker-room door hangs half off; the smell of fish and rust hasn\'t cleared in twenty years. Locker seventeen is at the back. Then dogs growl at the far end of the warehouse, and a flashlight beam sweeps the window.','A porta dos balneários está meio caída; o cheiro a peixe e ferrugem não saiu em vinte anos. O cacifo dezassete fica ao fundo. Então ouvem-se cães a rosnar no armazém, e uma lanterna varre a janela.')],choices:ch};
}
function c3_outcome(who,mode){
 const ok=who!=='alone'||mode==='shot'||(mode==='hide'&&c3_prepared());
 const M={shot:t('枪口朝下，一声枪响，野狗四散。你的手很稳。远处的手电光转向了别处——在德州，夜里的枪声多半是打野猪。','Muzzle down, one shot, and the dogs scatter. Your hand is steady. The far beam turns away — in Texas a shot at night is usually just someone after hogs.','Cano para baixo, um tiro, e os cães fogem. A tua mão está firme. A lanterna ao longe vira costas — no Texas, um tiro à noite é quase sempre alguém atrás de javalis.'),
  shaky:t('你拔枪时手在抖，子弹打中屋顶，一块锈铁皮轰然砸下。手电光朝这边冲了过来。','Your hand shakes; the shot hits the roof and a sheet of rusted iron crashes down. The beam comes running.','A mão treme; a bala acerta no telhado e cai uma chapa ferrugenta com estrondo. A lanterna vem a correr.'),
  hide:t('你关掉手电，贴着铁柜蹲下。狗叫近了，又远了。','You kill the light and crouch by the lockers. The barking comes close, then fades.','Apagas a lanterna e agachas-te junto aos cacifos. Os latidos chegam perto e afastam-se.'),
  friend:{beto:t('贝托没举枪，冲黑暗吹了声长口哨——狗叫停了。“它们是我家那条老母狗生的。”','Beto doesn\'t raise the gun. One long whistle into the dark, and the barking stops. "Pups of our old bitch."','O Beto não levanta a arma. Um assobio comprido para o escuro e os latidos param. «Filhos da nossa cadela velha.»'),
   lucia:t('露西娅撒下狗粮，轻声说话。领头那只瘸腿黄狗过来闻了闻她的手：“我给它接过腿。”','Lucía scatters the food and talks softly. A lame yellow dog comes and sniffs her hand. "I set his leg."','A Lucía espalha a ração e fala baixinho. Um cão amarelo e coxo cheira-lhe a mão. «Fui eu que lhe tratei a pata.»'),
   wade:t('韦德按着你的肩蹲进阴影，手电光从头顶扫过。他等了整整三分钟：“走。”','Wade presses you down into the shadows; the beam passes overhead. He waits three full minutes. "Go."','O Wade puxa-te para a sombra; o feixe passa por cima. Espera três minutos. «Vai.»'),
   roz:t('罗兹带你从锅炉房绕了出去又绕回来：“我在这儿做过三个月勘测。”','Roz takes you out through the boiler house and back in another way. "I surveyed this site for three months."','A Roz leva-te pela casa das caldeiras e volta a entrar por outro lado. «Fiz aqui sondagens durante três meses.»')}[who]||''}[mode];
 const save=who!=='alone'&&mode==='shaky'?[t('好在你不是一个人。同伴拽着你翻出后窗，等光走远才回来。','Good thing you\'re not alone. Your companion hauls you out the back window until the light is gone.','Ainda bem que não vieste sozinho. Quem vem contigo puxa-te pela janela até a luz se afastar.')]:[];
 if(ok){S.flags.evidence=true;S.flags.canneryWith=who;log('在十七号柜找到水质报告和和解协议','Found the water report and settlement in locker 17','Encontraste o relatório e o acordo no cacifo 17');
  if(who!=='alone')addTrust(who,2);
  return {title:t('十七号柜','Locker seventeen','Cacifo dezassete'),meta:t('证据到手','Evidence secured','Provas na mão'),text:[M,...save,
   S.flags.c3_key?t('铜钥匙卡了一下，转动了。','The brass key sticks, then turns.','A chave de latão emperra e depois roda.'):t('没有钥匙，你用撬棍撬开了柜门。','No key — you crowbar the door open.','Sem chave, abres a porta com o pé de cabra.'),
   t('油布包着一个文件袋：1998 年奥斯汀实验室的水质报告，数字用红笔圈着；和解协议副本，有汉克·博伊德的签名，也有若泽的。','An oilcloth packet: a 1998 Austin lab water report, numbers circled in red, and a copy of the settlement signed by Hank Boyd — and by José.','Um embrulho de oleado: um relatório de água de um laboratório de Austin, de 1998, com números a vermelho, e uma cópia do acordo assinada pelo Hank Boyd — e pelo José.'),
   t('最底下一张照片：若泽和工人们站在厂门口笑。背面写着：“我们赢了热水。1997。”','At the bottom, a photo: José and the workers grinning at the gate. On the back: "We won the hot water. 1997."','No fundo, uma fotografia: o José e os operários a sorrir ao portão. Nas costas: «Ganhámos a água quente. 1997.»')],
   choices:[{t:t('带着文件袋离开','Leave with the folder','Sair com a pasta'),next:c3_end}]};
 }
 S.flags.evidence=false;S.flags.canneryWith='alone';S.flags.c3_page=true;S.rep-=2;log('夜探罐头厂失败，只带回报告最后一页','Cannery search failed: only the report\'s last page','A busca falhou: só a última página do relatório');
 return {title:t('后窗','The back window','A janela das traseiras'),meta:t('空手而归','Empty-handed','De mãos vazias'),text:[M,
  t('光到了门口。你抓出一张纸就翻出后窗。回店才看清：报告的最后一页，只有签名和日期，没有数字。','The light reaches the door. You grab one sheet and go out the back window. At the shop you see it: the report\'s last page. A signature, a date, no numbers.','A luz chega à porta. Agarras uma folha e saltas a janela. No restaurante vês: a última página do relatório. Assinatura, data, nenhum número.'),
  t('你想起两个人：记得那些数字的老菲茨杰拉德，和知道工地日程的罗兹。推土机推得倒楼，推不倒记得的人。','You think of two people: Old Man Fitzgerald, who remembers the numbers, and Roz, who knows the site schedule. A bulldozer can flatten a building, not the people who remember.','Pensas em duas pessoas: o velho Fitzgerald, que se lembra dos números, e a Roz, que conhece a obra. Um bulldozer deita abaixo um edifício, não quem se lembra.')],
  choices:[{t:t('一瘸一拐地回店里','Limp back to the shop','Voltar a coxear'),next:c3_end}]};
}
function c3_end(){
 const sm=S.flags.sentMoney||0;
 const ev=S.flags.evidence?t('文件袋压在那叠信旁边。你终于明白舅舅为什么不回家：不是他做错了，而是他每次做对，都要赔上一切。','The folder lies beside the letters. At last you understand why your uncle never went home: not because he did wrong, but because every time he did right, it cost him everything.','A pasta está ao lado das cartas. Percebes finalmente porque o teu tio nunca voltou: não por ter feito mal, mas porque cada vez que fez bem lhe custou tudo.'):t('证据没拿到。但你知道它存在过，也知道谁还记得。','No evidence. But you know it existed, and who still remembers.','Sem provas. Mas sabes que existiram e quem ainda se lembra.');
 const st=S.flags.stormOpen?t('冰暴那一周的炉火，这个镇子会记很久。','This town will long remember your fire in the ice storm.','A vila vai lembrar-se muito tempo do teu lume na tempestade.'):t('冰暴那一周，你的店亮着，却没人在那里过夜。','In the ice storm your shop had light, but no one slept there.','Na tempestade o teu restaurante tinha luz, mas ninguém lá dormiu.');
 const mo=sm>0?t(`这个冬天，一共 $${sm} 寄回了里斯本。妈妈出院了。`,`This winter, $${sm} in all went home to Lisbon. Mom is out of hospital.`,`Este inverno foram $${sm} para Lisboa. A mãe já teve alta.`):t('这个冬天你没寄钱，但每晚都听着妈妈的声音睡着。她出院了。','You sent no money this winter, but fell asleep to your mother\'s voice every night. She\'s out of hospital.','Não mandaste dinheiro este inverno, mas adormeceste todas as noites com a voz da tua mãe. Já teve alta.');
 return {title:t('第三章 · 冬：罐头厂　完','End of Chapter 3 · Winter: The Cannery','Fim do Capítulo 3 · Inverno: A Fábrica'),meta:t(`第 36 周 · 现金 $${Math.round(S.cash)} · 口碑 ${Math.round(S.rep)}`,`Week 36 · Cash $${Math.round(S.cash)} · Reputation ${Math.round(S.rep)}`,`Semana 36 · Dinheiro $${Math.round(S.cash)} · Reputação ${Math.round(S.rep)}`),text:[ev,st,mo,
  t(`魅力 ${charm()} · 手艺 ${S.stats.oficio} · 德州味 ${S.stats.tex} · 乡愁 ${S.stats.saud}。若泽的信，你找到了 ${S.letters} 封。`,`Charm ${charm()} · Craft ${S.stats.oficio} · Texanness ${S.stats.tex} · Homesickness ${S.stats.saud}. You\'ve found ${S.letters} of José\'s letters.`,`Charme ${charm()} · Ofício ${S.stats.oficio} · Texanidade ${S.stats.tex} · Saudade ${S.stats.saud}. Encontraste ${S.letters} cartas do José.`),
  t('第四章「春：圣安东尼节」开始了。','Chapter 4, "Spring: Saint Anthony\'s Festival," begins.','Começa o Capítulo 4, «Primavera: Santo António».')],choices:[{t:t('继续这一年','Carry on with the year','Continuar o ano')}]};
}

STORY.push(
/* W25 — Inês arrives */
{id:'c3_arrive',when:c3At(25,1,0),run:()=>{
 const pre={title:t('蓝色北风','Blue norther','O norte azul'),meta:t('第三章 · 冬：罐头厂','Chapter 3 · Winter: The Cannery','Capítulo 3 · Inverno: A Fábrica'),text:[
  t('第一道北风夜里到了，停车场的水洼结了冰。厄尔说每年这时候都有人把皮卡开进沟里。','The first norther blew in overnight; the puddles in the lot are iced over. Earl says every year about now somebody puts a pickup in the ditch.','O primeiro vento do norte chegou de noite; as poças do parque gelaram. O Earl diz que todos os anos por esta altura alguém mete a carrinha na valeta.'),
  t('一辆出租车停在门口。先出来的是一只你认得的旧箱子，箱角还贴着你们去波尔图那年的贴纸。','A taxi pulls up. First out is an old suitcase you know, the sticker from your trip to Porto together still on its corner.','Um táxi para à porta. Primeiro sai uma mala velha que conheces, ainda com o autocolante da vossa viagem ao Porto.')],choices:[]};
 pre.choices=rel('ines').met?[{t:t('走出去','Go outside','Sair'),fx:()=>addLike('ines',1)}]:[{t:t('走出去','Go outside','Sair'),next:()=>meetScene('ines')}];
 return pre}},
{id:'c3_package',when:c3At(25,2,2),run:()=>({title:t('铁皮饼干盒','The biscuit tin','A lata de bolachas'),meta:t('伊内丝带来的','What Inês brought','O que a Inês trouxe'),text:[
 t('伊内丝从箱底拿出一个铁皮饼干盒：“你妈让我带的，说你现在该看了。”盒里是 1996 年的剪报：“渔船‘圣安东尼号’沉没，掌舵者弃船先逃。”有人用圆珠笔在“掌舵者”上来回划，划破了纸。','Inês takes a biscuit tin from her suitcase. "Your mother sent it. She said it\'s time you saw it." Inside, a 1996 clipping: "Fishing boat Santo António sinks; helmsman first to abandon ship." Someone has scored "helmsman" with a ballpoint until the paper tore.','A Inês tira da mala uma lata de bolachas. «Foi a tua mãe que mandou. Disse que está na hora de veres.» Lá dentro, um recorte de 1996: «Traineira Santo António afunda-se; homem do leme foi o primeiro a abandonar o barco.» Alguém riscou «homem do leme» até rasgar o papel.'),
 t('“还有，”她压低声音，“你妈比电话里瘦多了。她不让我说。”','"And," she says quietly, "your mom is much thinner than she sounds on the phone. She told me not to say."','«E», diz baixinho, «a tua mãe está muito mais magra do que parece ao telefone. Pediu-me para não dizer.»')],choices:[
 {t:t('和她一起读完剪报','Read the clipping with her','Ler o recorte com ela'),fx:()=>{addTrust('ines',1);stat('saud',4);S.lusoThisWeek=true;S.flags.c3_clip=1},
  next:()=>c3S('报上说若泽“下落不明”。伊内丝说：“报纸总站在活着的老人那边。”','The paper calls José "whereabouts unknown." Inês says: "Newspapers always side with the old man who\'s still alive."','O jornal diz que o José está «em parte incerta». A Inês diz: «Os jornais ficam sempre do lado do velho que está vivo.»')},
 {t:t('先问妈妈的事','Ask about your mother first','Perguntar primeiro pela mãe'),fx:()=>{addLike('ines',1);stat('saud',6);S.lusoThisWeek=true},
  next:()=>c3S('“她还天天去市场，只是走到一半要坐下。她问你冷不冷，我说德州不冷。”她看看窗外的冰，“我撒谎了。”','"She still goes to the market every day, just has to sit halfway. She asked if you\'re cold. I said Texas isn\'t cold." She looks at the ice outside. "I lied."','«Ainda vai ao mercado todos os dias, só tem de se sentar a meio. Perguntou se tens frio. Eu disse que o Texas não é frio.» Olha para o gelo lá fora. «Menti.»')},
 {t:t('把盒子收进若泽的书桌','Put the tin away in José\'s desk','Guardar a lata na secretária do José'),fx:()=>{stat('tex',2);addLike('ines',-1)}}]})},
{id:'c3_echo',when:c3At(25,5,1),run:()=>{
 const h=S.flags.homecoming;
 const line=h==='charm'?t('两个油田白领在学你返校赛那晚的样子：手搭椅背，眨眼。伊内丝问：“你在这里也这样？”','At lunch two oilfield guys imitate you on homecoming night: arm over the chair, a wink. Inês asks: "You do that here too?"','Ao almoço, dois do petróleo imitam-te na noite do homecoming: braço na cadeira, piscadela. A Inês pergunta: «Aqui também fazes isso?»')
  :h==='humor'?t('牧场工人还在重复你返校赛那晚的笑话。伊内丝没听懂笑点，但听懂了那种笑：是接纳。','At lunch the ranch hands are still repeating your homecoming joke. Inês misses the punchline but gets the laughter: it means you\'re in.','Ao almoço, os do rancho ainda repetem a tua piada do homecoming. A Inês não percebe a graça, mas percebe o riso: quer dizer que és dos deles.')
  :h==='truth'?t('阿尔贝蒂娜太太当着一屋子人对伊内丝说：“返校赛那晚，他站起来说了实话。这个镇子记得。”伊内丝看着你，像不太认识你了。','Dona Albertina tells Inês in front of everyone: "On homecoming night he stood up and told the truth. This town remembers." Inês looks at you as if she doesn\'t quite know you.','A Dona Albertina diz à Inês à frente de todos: «Na noite do homecoming ele levantou-se e disse a verdade. Esta terra não esquece.» A Inês olha para ti como se não te conhecesse bem.')
  :t('还有人问你返校赛那晚到底想说什么。伊内丝替你答：“他是阿尔法马来的，这已经够复杂了。”','Someone still asks what you meant on homecoming night. Inês answers for you: "He\'s from Alfama. That\'s complicated enough."','Alguém ainda pergunta o que querias dizer na noite do homecoming. A Inês responde: «Ele é de Alfama. Já é complicado que chegue.»');
 return {title:t('返校赛之后','After homecoming','Depois do homecoming'),meta:t('小城记性好','Small towns remember','As vilas não esquecem'),text:[line,t('“在里斯本，你从来不用回答‘你是谁’，”她说，“大家都知道你是谁家的孩子。”','"In Lisbon you never had to answer \'who are you,\'" she says. "Everyone knew whose kid you were."','«Em Lisboa nunca tiveste de responder "quem és tu"», diz ela. «Toda a gente sabia de quem eras filho.»')],choices:[
  {t:t('承认：在这里我得自己回答','Admit it: here I answer for myself','Admitir: aqui respondo por mim'),fx:()=>{addTrust('ines',1);stat('tex',2)}},
  {t:`[${faceWord()}] `+t('冲她笑笑，岔开话题','Smile and change the subject','Sorrir e mudar de assunto'),req:CHARM_REQ(50),fx:()=>{addLike('ines',1);flirt()}},
  {t:t('说你想念那种“不用回答”','Say you miss not having to answer','Dizer que tens saudades de não ter de responder'),fx:()=>{stat('saud',5);addLike('ines',1);S.lusoThisWeek=true}}]}}},
/* W26 — Old Man Fitzgerald, letter 8 */
{id:'c3_fitz1',when:c3At(26,3,1),run:()=>({title:t('老菲茨杰拉德','Old Man Fitzgerald','O velho Fitzgerald'),meta:t('罐头厂最后一任工头','The cannery\'s last foreman','O último capataz da fábrica'),text:[
 rel('colleen').met?t('科琳扶着一个戴褪色罐头厂工帽的老人进门：“我爷爷。听说你在用若泽的烤架，非要来看看。”','Colleen helps in an old man in a faded cannery cap. "My grandpa. Heard you\'re using José\'s grill and had to see."','A Colleen ajuda a entrar um velho de boné desbotado da fábrica. «O meu avô. Soube que usas a grelha do José e quis ver.»')
  :t('一个戴褪色罐头厂工帽的老人拄着拐杖进门：“我姓菲茨杰拉德，那个厂最后一个工头。”','An old man in a faded cannery cap comes in on a cane. "Name\'s Fitzgerald. Last foreman that plant had."','Entra de bengala um velho de boné desbotado da fábrica. «Chamo-me Fitzgerald. Fui o último capataz daquela fábrica.»'),
 t('他喝着羽衣甘蓝汤：“若泽杀鱼最快，嘴也最快。他让工人签名要热水、要手套。1998 年春天，汉克·博伊德叫我去开除他。我去了。”他放下勺子，“剩下的，下次说。”','Over kale soup: "José gutted fish faster than anybody, and talked faster. Got the crew signing for hot water and gloves. Spring of \'98, Hank Boyd sent me to fire him. I went." He sets down the spoon. "The rest, another time."','A beber caldo verde: «O José amanhava peixe mais depressa do que todos, e falava mais depressa. Pôs o pessoal a assinar por água quente e luvas. Na primavera de 98, o Hank Boyd mandou-me despedi-lo. Eu fui.» Pousa a colher. «O resto fica para outra vez.»')],choices:[
 {t:t('问他汉克·博伊德是什么样的人','Ask what Hank Boyd was like','Perguntar como era o Hank Boyd'),fx:()=>{S.flags.c3_fitz=1;addTrust('colleen',1)}},
 {t:t('不追问，再给他盛一碗汤','Don\'t push; bring him another bowl','Não insistir e servir outra tigela'),fx:()=>{S.flags.c3_fitz=2;stat('oficio',1);S.rep+=1},
  next:()=>c3S('他喝完第二碗，留了张纸条：“我还会来。”字写得很用力。','He finishes the second bowl and leaves a note: "I\'ll be back." Pressed hard into the paper.','Acaba a segunda tigela e deixa um bilhete: «Eu volto.» Escrito com força.')},
 {t:t('问店后那块空地','Ask about the lot out back','Perguntar pelo terreno das traseiras'),req:()=>S.stats.tex>=30||NEED(t('德州味 30','Texanness 30','Texanidade 30')),fx:()=>{S.flags.c3_fitz=3;stat('tex',1)},
  next:()=>c3S('他的眼神第一次锐利起来：“那块地是封口费，孩子。”','For the first time his eyes go sharp. "That lot was hush money, son."','Pela primeira vez o olhar dele fica afiado. «Aquele terreno foi o preço do silêncio, rapaz.»')}]})},
{id:'c3_letter8',when:c3At(26,6,2),run:()=>{letter(8);log('找到若泽的第 8 封信','Found José\'s letter #8','Encontraste a carta n.º 8 do José');
 return {title:t('若泽的第 8 封信','José\'s letter #8','A carta n.º 8 do José'),meta:t('圣安东尼号','The Santo António','O Santo António'),text:[
 t('你掏空烟熏炉的灰，在最底下摸到一个裹着锡纸的信封。','You shovel out the smoker\'s ash and find a foil-wrapped envelope at the bottom.','Tiras a cinza do fumeiro e encontras no fundo um envelope em papel de alumínio.'),
 t('“费尔南达：起风那晚，我劝爸爸别出海，他说债不等人。船翻时，厨子十六岁的儿子被缆绳缠住。我放开舵，跳下去割绳。等我们浮上来，船已经没了。”','"Fernanda: the night the wind rose, I begged Father not to go out. He said debts don\'t wait. When she rolled, the cook\'s sixteen-year-old boy was caught in the lines. I let go of the wheel and went in to cut him free. When we came up, the boat was gone."','«Fernanda: na noite em que se levantou o vento, pedi ao pai para não sairmos. Ele disse que as dívidas não esperam. Quando o barco virou, o filho do cozinheiro, de dezasseis anos, ficou preso nos cabos. Larguei o leme e atirei-me para o soltar. Quando viemos à tona, o barco já não estava.»'),
 t('“爸爸在码头上说，是我丢下了舵。我没反驳。他已经没了船，我不想他再没了脸面。那孩子现在在塞图巴尔开出租，每年圣诞给我寄张卡片。这是我这辈子唯一拿得出手的东西。”','"On the quay Father said I\'d abandoned the wheel. I didn\'t argue. He\'d lost his boat; I didn\'t want him to lose face too. That boy drives a taxi in Setúbal now and sends me a card every Christmas. It\'s the one thing in my life I\'m proud of."','«No cais, o pai disse que eu tinha abandonado o leme. Não o contrariei. Ele já tinha perdido o barco; não queria que perdesse a cara. Esse rapaz é taxista em Setúbal e manda-me um postal todos os Natais. É a única coisa de que me orgulho.»')],choices:[
 {t:t('拍下来发给鲁伊','Send a photo of it to Rui','Mandar uma fotografia ao Rui'),fx:()=>{stat('saud',5);S.lusoThisWeek=true;S.flags.c3_rui=1},
  next:()=>c3S('鲁伊很久才回：“妈不知道这些。先别告诉她，等她好一点。”','Rui takes a long time to answer. "Mom doesn\'t know any of this. Don\'t tell her yet. Wait till she\'s better."','O Rui demora a responder. «A mãe não sabe nada disto. Não lhe digas ainda. Espera que melhore.»')},
 {t:t('读给伊内丝听','Read it to Inês','Lê-la à Inês'),req:()=>rel('ines').met||NEED(t('认识伊内丝','Know Inês','Conhecer a Inês')),fx:()=>addTrust('ines',2),
  next:()=>c3S('她听完说：“你们家的男人，宁可背骂名也不开口。”她顿了顿，“你也是。”','"The men in your family would rather carry the blame than open their mouths." A pause. "You too."','«Os homens da tua família preferem carregar a culpa a abrir a boca.» Uma pausa. «Tu também.»')},
 {t:t('一个人坐到天亮','Sit alone until dawn','Ficar sozinho até de madrugada'),fx:()=>{stat('saud',8);stat('oficio',1)}}]}}},
/* W27 — Travis turns the screws */
{id:'c3_inspect',when:c3At(27,2,0),run:()=>({title:t('突击检查','Surprise inspection','Inspeção-surpresa'),meta:t('县卫生局','County health department','Saúde do condado'),text:[
 t('早上七点，卫生检查员已经在门口：“匿名投诉，说你冷库温度不达标，后院乱生火。”','Seven a.m. and the health inspector is at the door. "Anonymous complaint. Says your walk-in runs warm and you\'re lighting fires out back."','Sete da manhã e o inspetor de saúde já está à porta. «Denúncia anónima. Diz que a câmara frigorífica não está à temperatura e que fazes fogueiras no quintal.»'),
 c3_lic()?t('他翻了一页：“你的酒类执照刚批不久吧？分数低于七十，执照复审会很难看。”','He flips a page. "Liquor license is pretty new, huh? Score under seventy and the review gets ugly."','Vira a página. «A licença de álcool é recente, não é? Abaixo de setenta, a revisão corre mal.»')
  :t('他翻了一页：“执照没批下来，是吧？分数再难看，明年也别想再申请了。”','He flips a page. "Liquor license got turned down, right? Score badly and forget reapplying next year."','Vira a página. «A licença foi recusada, não foi? Com má nota, esquece voltar a pedir para o ano.»')],choices:[
 {t:t('带他逐项检查：温度记录、进货单、灭火器','Walk him through temp logs, invoices, extinguisher','Mostrar-lhe registos, faturas e extintor'),req:()=>S.stats.oficio>=45||NEED(t('手艺 45','Craft 45','Ofício 45')),fx:()=>{S.rep+=2;S.flags.c3_insp='clean'},
  next:()=>c3S('九十四分。他走前压低声音：“投诉电话是博伊德公司的座机打的。你没听我说过。”','Ninety-four. On his way out, quietly: "That call came from a Boyd company line. You didn\'t hear it from me."','Noventa e quatro. À saída, baixinho: «A chamada veio de um telefone da empresa do Boyd. Não fui eu que disse.»')},
 {t:`[${faceWord()}] `+t('请他喝杯咖啡聊聊','Pour him a coffee and chat','Servir-lhe um café e conversar'),req:CHARM_REQ(55),fx:()=>{flirt();S.flags.c3_insp='charm'}},
 {t:t('老实认错，交 $150 罚款','Own up and pay the $150 fine','Admitir e pagar $150 de multa'),fx:()=>{S.cash-=150;S.rep-=1;S.flags.c3_insp='fine'}}]})},
{id:'c3_travis2',when:c3At(27,4,2),run:()=>({title:t('特拉维斯的第二次','Travis, round two','Travis, segunda volta'),meta:t('孤星酒吧','The Lone Star Saloon','O Lone Star Saloon'),text:[
 t('特拉维斯在你旁边坐下：“听说卫生局去你那儿了？一个电话的事。”他推过一张纸：$60,000。“你妈身体不好吧？里斯本的医院可不便宜。”','Travis sits down beside you. "Heard the health department paid a visit? Just takes one phone call." He slides over a paper: $60,000. "Your mama\'s not well, is she? Lisbon hospitals ain\'t cheap."','O Travis senta-se ao teu lado. «Soube que a saúde te foi visitar? Basta um telefonema.» Empurra um papel: $60.000. «A tua mãe não anda bem, pois não? Os hospitais em Lisboa não são baratos.»'),
 t('你从没跟他提过你母亲。“遗嘱是公开存档的，我读过。要是哪个礼拜店被封了……”他耸耸肩。','You have never mentioned your mother to him. "That will\'s public record. I read it. Now if the place got shut down some week…" He shrugs.','Nunca lhe falaste da tua mãe. «O testamento é público. Li-o. Se o restaurante for fechado numa semana qualquer…» Encolhe os ombros.')],choices:[
 {t:t('把纸推回去：“这块地不卖。”','Push it back: "Not for sale."','Devolver o papel: «Não está à venda.»'),fx:()=>{S.flags.c3_travis='refuse';stat('tex',3);addTrust('earl',1);S.rep+=1},
  next:()=>c3S('他笑了，还是不看你的眼睛：“那就看看你的烤架能撑几个冬天。”','He smiles, eyes elsewhere. "Then let\'s see how many winters that grill can take."','Sorri, de olhos noutro lado. «Então vamos ver quantos invernos aguenta essa grelha.»')},
 {t:t('问：“一块停车场，值六万？”','Ask: "Sixty grand for a parking lot?"','Perguntar: «Sessenta mil por um parque?»'),req:()=>S.stats.tex>=35||charm()>=60||NEED(t('德州味 35 或魅力 60','Texanness 35 or Charm 60','Texanidade 35 ou Charme 60')),fx:()=>{S.flags.c3_travis='probe';addLike('roz',1)},
  next:()=>c3S('他的笑停了半秒：“有些地方，位置比面积值钱。”说完他就后悔了。角落里，罗兹也听见了。','His smile stalls. "Some places, location\'s worth more than acreage." He regrets it at once. In the corner, Roz heard it too.','O sorriso para. «Há sítios em que a localização vale mais do que a área.» Arrepende-se logo. Ao canto, a Roz também ouviu.')},
 {t:t('说你会考虑','Say you\'ll think about it','Dizer que vais pensar'),fx:()=>{S.flags.c3_travis='stall';addTrust('earl',-1)}}]})},
/* W28 — Christmas */
{id:'c3_treats',when:c3At(28,1,1),run:()=>({title:t('两种圣诞点心','Two Christmas treats','Dois doces de Natal'),meta:t('主街挂起了彩灯','Lights on Main Street','Luzes na rua principal'),text:[
 t('阿尔贝蒂娜太太端着面团来炸亚速尔圣诞油饼；十分钟后玛丽索尔抱着一锅玉米粽子也来了。两人在灶台前对视三秒，同时开口：“你那油温不对。”','Dona Albertina brings dough for Azorean Christmas fritters; ten minutes later Marisol arrives with a pot of tamales. They stare each other down at the stove, then say at once: "Your oil\'s the wrong temperature."','A Dona Albertina traz massa para filhoses; dez minutos depois chega a Marisol com uma panela de tamales. Encaram-se ao fogão e dizem ao mesmo tempo: «Esse óleo não está à temperatura certa.»')],choices:[
 {t:t('两样都上菜单：“圣诞拼盘”','Both on the menu: the "Christmas Platter"','Ambos na ementa: a «Travessa de Natal»'),fx:()=>{S.rep+=3;S.cash+=120;addLike('albertina',1);addLike('marisol',1);stat('tex',2)},
  next:()=>c3S('拼盘卖了一下午。汤米的直播有四百人看，三百人在评论区吵哪个好吃。','The platter sells all afternoon. Tommy\'s livestream gets four hundred viewers; three hundred argue about which is better.','A travessa vende a tarde toda. A transmissão do Tommy tem quatrocentas pessoas; trezentas discutem qual é melhor.')},
 {t:t('站在阿尔贝蒂娜这边','Side with Albertina','Ficar do lado da Albertina'),fx:()=>{addLike('albertina',2);addLike('marisol',-1);stat('saud',3);S.lusoThisWeek=true}},
 {t:t('让她们比赛，你当裁判','Make it a contest; you judge','Fazer um concurso; tu és o júri'),req:()=>S.stats.tex>=25||NEED(t('德州味 25','Texanness 25','Texanidade 25')),fx:()=>{S.online+=4;addTrust('albertina',1);addTrust('marisol',1)}}]})},
{id:'c3_consoada',when:c3At(28,3,2),run:()=>({title:t('平安夜','Christmas Eve','Consoada'),meta:t('第 28 周','Week 28','Semana 28'),text:[
 t('平安夜。里斯本那边，妈妈会把鳕鱼、土豆和甘蓝摆满一桌，留一把空椅子给不在的人。小时候你不知道那把椅子是给谁的。现在你知道了。','Christmas Eve. In Lisbon, Mom covers the table with salt cod, potatoes and cabbage and leaves an empty chair for whoever isn\'t there. As a kid you never knew who it was for. Now you do.','Consoada. Em Lisboa, a mãe enche a mesa de bacalhau, batatas e couves e deixa uma cadeira vazia para quem não está. Em pequeno nunca soubeste para quem era. Agora sabes.'),
 t('阿尔贝蒂娜说：“七点，我家，鳕鱼。不来我就去拖你。”厄尔的酒吧也照常开着。','Albertina\'s orders: "Seven, my house, salt cod. Don\'t come and I\'ll drag you." Earl\'s bar is open as always.','A Albertina avisou: «Sete horas, minha casa, bacalhau. Se não vieres, vou buscar-te.» O bar do Earl está aberto, como sempre.')],choices:[
 {t:t('去阿尔贝蒂娜家吃鳕鱼','Salt cod at Albertina\'s','Bacalhau em casa da Albertina'),fx:()=>{stat('saud',5);S.lusoThisWeek=true;addLike('albertina',2);addTrust('albertina',2);if(rel('ines').met)addTrust('ines',1);S.flags.c3_xmas='albertina'},
  next:()=>c3S('她桌边也有一把空椅子——若泽的位子，二十多年每年都摆。你坐了上去。没人说话，所有人都举起了杯。','There\'s an empty chair at her table too — José\'s place, set every year for twenty years. You sit in it. No one speaks. Everyone raises a glass.','Também há uma cadeira vazia à mesa dela — o lugar do José, posto todos os anos há vinte anos. Sentas-te. Ninguém fala. Todos levantam o copo.')},
 {t:t('去厄尔的酒吧，陪没地方去的人','Go to Earl\'s, keep the strays company','Ir ao Earl fazer companhia a quem está só'),fx:()=>{stat('tex',4);addTrust('earl',2);S.flags.c3_xmas='earl'},
  next:()=>c3S('快十二点时，厄尔倒了两杯波本，一杯推到吧台空着的那头：“若泽的。”','Near midnight Earl pours two bourbons and slides one to the empty end of the bar. "José\'s."','Perto da meia-noite, o Earl serve dois bourbons e empurra um para a ponta vazia do balcão. «O do José.»')},
 {t:t('开店，给赶路的卡车司机做夜宵','Open up and feed the truckers','Abrir para os camionistas'),fx:()=>{S.cash+=220;S.rep+=2;stat('saud',6);S.flags.c3_xmas='shop'},
  next:()=>c3S('打烊时你才想起没给家里打电话。里斯本已经是圣诞早上了。','Only at closing do you remember you never called home. In Lisbon it\'s already Christmas morning.','Só ao fechar te lembras de que não ligaste para casa. Em Lisboa já é manhã de Natal.')},
 {t:t('视频打给家里','Video-call home','Videochamada para casa'),fx:()=>{stat('saud',8);S.lusoThisWeek=true;S.flags.c3_xmas='home'},
  next:()=>c3S('屏幕里，妈妈脸色发灰，一直在笑：“你那边也有鳕鱼吗？”你撒谎说有。','On the screen Mom is grey in the face and smiling the whole time. "Do you have salt cod there?" You lie and say yes.','No ecrã, a mãe está cinzenta e sempre a sorrir. «Aí há bacalhau?» Mentes e dizes que sim.')}]})},
/* W29-30 — the ice storm */
{id:'c3_storm1',when:c3At(29,2,0),run:()=>({title:t('冰暴','The ice storm','A tempestade de gelo'),meta:t('第 29 周 · 全镇停电','Week 29 · Blackout','Semana 29 · Apagão'),text:[
 t('冻雨下了一夜。电线垂地，树枝折断，州际公路封了，停电至少一周。只有你的店有若泽留下的两垛橡木，和一个能烧三天三夜的烟熏炉。','Freezing rain all night. Power lines down, limbs snapping, the interstate closed, a week without power at least. Only your shop has José\'s two stacks of oak and a smoker that burns three days straight.','Chuva gelada a noite toda. Cabos no chão, ramos partidos, a autoestrada fechada, pelo menos uma semana sem luz. Só o teu restaurante tem as duas pilhas de carvalho do José e um fumeiro que arde três dias seguidos.'),
 t('中午前就有人敲门：抱孩子的年轻妈妈，开不了车的老人，还有戴尔牧师和半个唱诗班。','By noon there\'s knocking: a young mother with a baby, old folks who can\'t drive, Pastor Dale and half the choir.','Antes do meio-dia batem à porta: uma mãe com um bebé, velhotes sem carro, o Pastor Dale e meio coro.')],choices:[
 {t:t('开门，生火，全部免费','Open up, light the fire — all free','Abrir e acender o lume — tudo grátis'),fx:()=>{S.flags.stormOpen=true;S.cash-=300;S.rep+=12;c3_trustAll(1);log('冰暴中免费开火：−$300，口碑 +12，所有人信任 +1','Free fire in the storm: −$300, reputation +12, everyone\'s trust +1','Lume grátis na tempestade: −$300, reputação +12, confiança +1')},
  next:()=>c3S('你把冷库里会坏的肉全烤了。“反正要坏，”你对自己说，“不如坏在大家肚子里。”','You grill every bit of meat that would spoil. "It\'ll rot anyway," you tell yourself. "Might as well rot in people\'s bellies."','Grelhas toda a carne que se ia estragar. «Estraga-se de qualquer maneira», dizes. «Mais vale na barriga das pessoas.»')},
 {t:t('请贝托拉来牧场的发电机和冻肉','Get Beto to bring the ranch generator and beef','Pedir ao Beto o gerador e a carne do rancho'),req:()=>c3_ok('beto',5)||NEED(t('贝托信任 5','Beto trust 5','Confiança do Beto 5')),fx:()=>{S.flags.stormOpen=true;S.cash-=100;S.rep+=12;c3_trustAll(1);addTrust('beto',1);addLike('lucia',1);log('和雷耶斯家一起开火：口碑 +12，所有人信任 +1','Kept the fire with the Reyes family: reputation +12, everyone\'s trust +1','Lume com a família Reyes: reputação +12, confiança +1')},
  next:()=>c3S('贝托的皮卡碾着冰开进来，车斗里是发电机和半头冻牛。“上次若泽也这么干，”他说，“那次我没来帮忙。”','Beto\'s pickup crunches in over the ice, a generator and half a frozen steer in the bed. "José did this last time," he says. "That time I didn\'t come help."','A carrinha do Beto entra a esmagar o gelo, com um gerador e meia vaca congelada. «Da outra vez o José fez isto», diz. «Dessa vez eu não vim ajudar.»')},
 {t:t('开门，按平常价钱收','Open, at normal prices','Abrir, a preço normal'),fx:()=>{S.flags.stormOpen=false;S.cash+=350;S.rep-=6;addTrust('dale',-1)},
  next:()=>c3S('大家付了钱，吃饱了。门口有人小声说：“上次若泽可没收钱。”','People pay and eat. At the door someone mutters: "José never charged last time."','Pagam e comem. À porta alguém resmunga: «Da outra vez o José não cobrou.»')},
 {t:t('关门，自己守着火','Lock up and keep the fire to yourself','Fechar e guardar o lume para ti'),fx:()=>{S.flags.stormOpen=false;stat('saud',4);S.rep-=3}}]})},
{id:'c3_storm2',when:c3At(29,4,2),run:()=>{
 if(S.flags.stormOpen)return {title:t('炉火边','By the fire','Junto ao lume'),meta:t('冰暴第三夜','Third night of the storm','Terceira noite'),text:[
  t('地上铺满睡袋，炉火照着四十张脸。','Sleeping bags everywhere; the fire lights forty faces.','Sacos-cama por todo o lado; o lume ilumina quarenta caras.'),
  t('戴尔牧师看了很久的火：“上一场冰暴，若泽也这么开过门。我跟会众说，那个天主教徒的火不干净。”他停了停，“我错了。”','Pastor Dale watches the fire a long time. "Last ice storm, José opened his doors like this. I told my flock that Catholic\'s fire wasn\'t clean." A pause. "I was wrong."','O Pastor Dale fica muito tempo a olhar o lume. «Na última tempestade, o José abriu as portas assim. Eu disse à congregação que o lume daquele católico não era limpo.» Pausa. «Enganei-me.»')],choices:[
  {t:t('陪牧师坐一会儿','Sit with the pastor','Ficar com o pastor'),fx:()=>{addTrust('dale',2);S.flags.c3_daleLicense=1},
   next:()=>c3S(c3_lic()?'他提起执照：“春天复审，我投赞成。”':'他提起执照：“春天再递一次申请。这次我不反对。”',c3_lic()?'He brings up the license. "Come the spring review, I vote yes."':'He brings up the license. "Apply again come spring. This time I won\'t stand in the way."',c3_lic()?'Fala da licença. «Na revisão da primavera, voto a favor.»':'Fala da licença. «Volta a pedir na primavera. Desta vez não me oponho.»')},
  {t:t('去听老菲茨杰拉德说话','Go hear Fitzgerald out','Ir ouvir o Fitzgerald'),fx:()=>{S.flags.c3_fitz=Math.max(S.flags.c3_fitz||0,2);addTrust('colleen',1)},
   next:()=>c3S('“半夜会有罐车从厂后门开出去，装的不是鱼。若泽拍过照，问我看见没有。我说没有。”火光里，老人的手在抖。','"Middle of the night, a tank truck\'d roll out the back gate, and it wasn\'t fish. José took pictures. Asked had I seen it. I said no." In the firelight the old man\'s hands shake.','«A meio da noite saía um camião-cisterna pelas traseiras, e não era peixe. O José tirou fotografias. Perguntou se eu tinha visto. Eu disse que não.» À luz do lume, as mãos do velho tremem.')},
  {t:t('弹一段葡萄牙吉他','Play the Portuguese guitar','Tocar guitarra portuguesa'),req:()=>S.stats.saud>=40||NEED(t('乡愁 40','Homesickness 40','Saudade 40')),fx:()=>{S.rep+=3;stat('saud',4);S.lusoThisWeek=true;addLike('albertina',1)},
   next:()=>c3S('没人听得懂法多的词，到第二段，有人跟着哼。窗外的冰从树上掉下来，像远处有人在敲碎玻璃。','No one understands the fado\'s words; by the second verse, people hum along. Outside, ice falls from the trees like glass breaking far away.','Ninguém percebe a letra do fado; à segunda estrofe já há quem trauteie. Lá fora o gelo cai das árvores como vidro a partir-se ao longe.')}]};
 return {title:t('黑暗的店','The dark shop','O restaurante às escuras'),meta:t('冰暴第三夜','Third night of the storm','Terceira noite'),text:[
  t('你裹着毯子坐在楼上。主街一片漆黑，只有厄尔的酒吧亮着发电机的黄灯。楼下有人敲门，敲了很久，然后走了。','You sit upstairs in blankets. Main Street is black except Earl\'s bar, yellow off a generator. Someone knocks downstairs, a long time, then leaves.','Estás lá em cima enrolado em mantas. A rua está às escuras, menos o bar do Earl, amarelo de gerador. Alguém bate lá em baixo, muito tempo, e vai-se.')],choices:[
  {t:t('下楼开门','Go down and open up','Descer e abrir'),fx:()=>{S.rep+=4;addTrust('albertina',1);S.cash-=60},
   next:()=>c3S('门外是阿尔贝蒂娜太太。她一言不发地走进来，点着了烟熏炉：“若泽从不让这个炉子在冬天凉着。”','It\'s Dona Albertina. Without a word she walks in and lights the smoker. "José never let this stove go cold in winter."','É a Dona Albertina. Entra sem dizer nada e acende o fumeiro. «O José nunca deixou este forno arrefecer no inverno.»')},
  {t:t('不去管','Leave it','Deixar estar'),fx:()=>{stat('saud',6);S.rep-=2}}]}}},
{id:'c3_roz1',when:c3At(30,5,2),run:()=>{S.flags.c3_lss=1;const fresh=!rel('roz').met;if(fresh){rel('roz').met=true;rel('roz').like=1}
 log('得知孤星砂业买下了罐头厂','Learned Lone Star Sand LLC owns the cannery','Soubeste que a Lone Star Sand LLC é dona da fábrica');
 return {title:t('孤星砂业','Lone Star Sand','Lone Star Sand'),meta:t('罗兹·梅菲尔德','Roz Mayfield','Roz Mayfield'),text:[
 ...(fresh?[t('一个穿油田工装的女人坐到你旁边：“罗兹，特拉维斯手下的工程师。我也不喜欢他。”','A woman in oilfield coveralls sits beside you. "Roz. I engineer for Travis. I don\'t like him either."','Uma mulher de fato-macaco senta-se ao teu lado. «Roz. Sou engenheira do Travis. Também não gosto dele.»')]:[]),
 t('罗兹把一份县地产登记拍在吧台上：“罐头厂卖给了‘孤星砂业’，签字的是特拉维斯的会计。”','Roz slaps a county deed record on the bar. "The cannery sold to Lone Star Sand LLC. Signed by Travis\'s accountant."','A Roz bate com uma cópia do registo predial no balcão. «A fábrica foi vendida à Lone Star Sand LLC. Assinou o contabilista do Travis.»'),
 t('“他要把那儿改成压裂砂中转站。州里要修新匝道，罐头厂接辅路只有一条路——”她用指甲划了一道，“穿过你店后的空地。开发要做环境评估。他怕的不是你，是地底下的东西。”','"He wants a frac-sand transload yard. The state\'s building a new ramp, and the only way the cannery reaches the frontage road—" she draws a line with her nail, "—is through the lot behind your shop. Building means an environmental assessment. It\'s not you he\'s scared of. It\'s what\'s in the ground."','«Quer um terminal de areia de fracturação. O estado vai fazer um novo acesso, e a fábrica só chega à estrada por um caminho —» risca com a unha, «— o terreno atrás do teu restaurante. Construir obriga a avaliação ambiental. Não é de ti que ele tem medo. É do que está debaixo da terra.»')],choices:[
 {t:t('问她：“你为什么告诉我？”','Ask: "Why tell me?"','Perguntar: «Porque me contas?»'),fx:()=>addTrust('roz',2),
  next:()=>c3S('“因为我签过字的井，没有一口是脏的。我不想第一口签在这儿。”','"Because every well I ever signed off on was clean. I don\'t want the first dirty one to be here."','«Porque todos os poços que assinei estavam limpos. Não quero que o primeiro sujo seja aqui.»')},
 {t:t('请她帮忙找更多','Ask her to dig up more','Pedir-lhe que descubra mais'),req:()=>rel('roz').trust>=3||NEED(t('罗兹信任 3','Roz trust 3','Confiança da Roz 3')),fx:()=>{S.flags.c3_rozHelp=1;addTrust('roz',1)}},
 {t:t('答应绝不说出消息来源','Promise no one will know it was her','Prometer que ninguém saberá que foi ela'),fx:()=>{addLike('roz',1);addTrust('roz',1);S.flags.c3_rozSecret=1}}]}}},
/* W31 — Mother in hospital */
{id:'c3_mom',when:c3At(31,1,0),run:()=>{log('母亲住院了','Your mother is in hospital','A tua mãe foi internada');
 return {title:t('凌晨四点的电话','A call at four a.m.','Uma chamada às quatro da manhã'),meta:t('第 31 周 · 里斯本','Week 31 · Lisbon','Semana 31 · Lisboa'),text:[
 t('鲁伊的声音是哑的：“妈住院了。肺炎，心脏也不好，昨晚送进了圣若泽医院。”——跟舅舅一个名字。','Rui\'s voice is hoarse. "Mom\'s in hospital. Pneumonia, and her heart. They took her into São José last night." Same name as your uncle.','O Rui está rouco. «A mãe foi internada. Pneumonia, e o coração. Levaram-na ontem para São José.» O mesmo nome do teu tio.'),
 t('“暂时稳住了。可你能回来吗？就一个星期。还有，账单已经来了，比我一个月工资还多。”','"She\'s stable for now. But can you come? Just a week. And the bills are already here — more than I make in a month."','«Para já está estável. Mas podes vir? Só uma semana. E as contas já chegaram — mais do que ganho num mês.»')],
 choices:[{t:t('订最早的机票回家','Book the first flight home','Marcar o primeiro voo'),next:c3_graceWill},...c3_momChoices()]}}},
{id:'c3_mom2',when:c3At(31,4,2),run:()=>{const m=S.flags.c3_mom;
 const a=m==='money'?t('鲁伊发来照片：妈妈插着氧气管，比了个大拇指。','Rui sends a photo: Mom on oxygen, giving a thumbs-up.','O Rui manda uma fotografia: a mãe com oxigénio, de polegar para cima.')
  :m==='grace'?t('鲁伊说，德州汇来一笔钱，汇款人写着“若泽”。妈妈看了很久，哭了。','Rui says money came from Texas, the sender listed as "José." Mom stared at it a long time and cried.','O Rui diz que chegou dinheiro do Texas, em nome de «José». A mãe olhou muito tempo e chorou.')
  :t('第四个晚上，她的声音比第一天亮了一点。','By the fourth night her voice is a little brighter.','À quarta noite a voz dela está um pouco mais clara.');
 return {title:t('病房里的屏幕','A screen in the ward','Um ecrã na enfermaria'),meta:t('圣若泽医院','São José Hospital','Hospital de São José'),text:[a,t('妈妈问：“你舅舅在那边过得好吗？他提起过我吗？”','Mom asks: "Was your uncle all right there? Did he ever mention me?"','A mãe pergunta: «O teu tio estava bem aí? Alguma vez falou de mim?»')],choices:[
 {t:t('把第 8 封信念给她听','Read her letter #8','Ler-lhe a carta n.º 8'),req:()=>S.letters>=8||NEED(t('第 8 封信','Letter #8','Carta n.º 8')),fx:()=>{S.flags.c3_toldMom=1;stat('saud',4);S.lusoThisWeek=true},
  next:()=>c3S('念到“我放开了舵”，妈妈闭上眼睛。很久以后她说：“我一直知道。爸爸临死前也知道。只是谁都没说。”','At "I let go of the wheel," Mom closes her eyes. Much later she says: "I always knew. Father knew before he died. Nobody ever said it."','Em «larguei o leme», a mãe fecha os olhos. Muito depois diz: «Eu sempre soube. O pai também, antes de morrer. Ninguém o disse.»')},
 {t:t('说：“他每天都想着你。”','Say: "He thought of you every day."','Dizer: «Pensava em ti todos os dias.»'),fx:()=>stat('charme',1),
  next:()=>c3S('这不是谎话，但也不是全部。妈妈笑了。她听出来了。','It isn\'t a lie, but it isn\'t all of it. Mom smiles. She can tell.','Não é mentira, mas não é tudo. A mãe sorri. Percebeu.')},
 {t:t('说你还在找答案','Say you\'re still looking','Dizer que ainda procuras'),fx:()=>stat('tex',1)}]}}},
/* W32 — letter 9, the foreman's confession */
{id:'c3_letter9',when:c3At(32,2,1),run:()=>{letter(9);log('找到若泽的第 9 封信','Found José\'s letter #9','Encontraste a carta n.º 9 do José');
 return {title:t('若泽的第 9 封信','José\'s letter #9','A carta n.º 9 do José'),meta:t('罐头厂','The cannery','A fábrica'),text:[
 t('后院棚梁上，你发现一个绑着渔网线的玻璃罐，里面卷着信纸。','On a rafter in the back shed you find a glass jar tied with fishing line, a letter rolled inside.','Numa trave do barracão encontras um frasco atado com fio de pesca, com uma carta enrolada.'),
 t('“费尔南达：每天夜里两点，厂后门开出一辆罐车，往东边旧井里倒东西。后来那边的牛开始掉毛。我取了水样送去奥斯汀。报告回来那天，汉克请我喝酒。第二天，我没了工作。我又一次站在对的一边，又一次失去一切。也许爸爸说得对，我就是会把船弄沉的人。”','"Fernanda: every night at two a tank truck leaves by the back gate and empties into the old well to the east. Then the cattle out there began losing their hair. I sent water samples to Austin. The day the report came back, Hank bought me a drink. The next day I had no job. Once again I stood on the right side and lost everything. Maybe Father was right. Maybe I\'m the kind of man who sinks boats."','«Fernanda: todas as noites às duas sai um camião-cisterna pelas traseiras e despeja no poço velho a nascente. Depois o gado de lá começou a perder o pelo. Mandei amostras de água para Austin. No dia em que veio o relatório, o Hank pagou-me um copo. No dia seguinte fiquei sem emprego. Mais uma vez fiquei do lado certo e perdi tudo. Se calhar o pai tinha razão. Sou o tipo de homem que afunda barcos.»')],choices:[
 {t:t('去问贝托“东边的旧井”','Ask Beto about "the old well to the east"','Perguntar ao Beto pelo «poço a nascente»'),req:()=>rel('beto').met||NEED(t('认识贝托','Know Beto','Conhecer o Beto')),fx:()=>{addTrust('beto',1);S.flags.c3_beto=1},
  next:()=>c3S('贝托沉默很久：“在我家东边围栏外。1998 年，我们死了十一头牛。若泽说他会想办法，后来开了店就不提了。我一直以为他收了钱。”','Beto is quiet a long time. "Past our east fence. In \'98 we lost eleven head. José said he\'d do something, then opened the shop and never brought it up. I always figured he took the money."','O Beto fica muito calado. «Para lá da nossa cerca a nascente. Em 98 morreram-nos onze cabeças. O José disse que ia resolver, depois abriu o restaurante e nunca mais falou nisso. Sempre achei que aceitou o dinheiro.»')},
 {t:t('给科琳打电话','Call Colleen','Ligar à Colleen'),req:()=>rel('colleen').met||NEED(t('认识科琳','Know Colleen','Conhecer a Colleen')),fx:()=>{addTrust('colleen',1);S.flags.c3_colleen=1},
  next:()=>c3S('“化验报告？如果它还在，就是这个县二十年来最大的新闻。也是我爷爷最怕的东西。”','"A lab report? If it still exists, it\'s the biggest story this county\'s had in twenty years. And what my grandpa fears most."','«Um relatório? Se ainda existir, é a maior notícia do condado em vinte anos. E aquilo de que o meu avô mais tem medo.»')},
 {t:t('把信和剪报摆在一起','Lay the letter beside the clipping','Pôr a carta ao lado do recorte'),fx:()=>stat('saud',3)}]}}},
{id:'c3_fitz2',when:c3At(32,6,2),run:()=>{S.flags.c3_locker17=1;
 return {title:t('工头的忏悔','The foreman\'s confession','A confissão do capataz'),meta:t('老菲茨杰拉德','Old Man Fitzgerald','O velho Fitzgerald'),text:[
 t('老菲茨杰拉德又来了，一个人。“开除若泽那天，他把柜子钥匙挂在脖子上，说：‘老菲，哪天你敢说实话了，十七号柜里有你要的东西。’我一直没敢，二十多年。”他看着你，“可孙女说，特拉维斯的人要拆更衣室了。”','Old Man Fitzgerald is back, alone. "Day I fired José, he had his locker key round his neck. Said, \'Fitz, the day you\'ve got the nerve to tell the truth, what you need is in seventeen.\' I never had the nerve. Twenty-some years." He looks at you. "But my granddaughter says Travis\'s people are fixing to tear down the locker room."','O velho Fitzgerald voltou, sozinho. «No dia em que despedi o José, ele tinha a chave do cacifo ao pescoço. Disse: "Fitz, no dia em que tiveres coragem de dizer a verdade, o que precisas está no dezassete." Nunca tive coragem. Mais de vinte anos.» Olha para ti. «Mas a minha neta diz que a gente do Travis vai deitar abaixo os balneários.»')],choices:[
 {t:t('“您愿意以后出来作证吗？”','"Would you testify, when it\'s time?"','«Testemunharia, quando for altura?»'),req:()=>(S.flags.c3_fitz||0)>=2||rel('colleen').trust>=4||NEED(t('和老菲茨杰拉德的交情','Rapport with Old Man Fitzgerald','Confiança do velho Fitzgerald')),fx:()=>{S.flags.c3_fitzWilling=true;addTrust('colleen',1)},
  next:()=>c3S('他攥着拐杖，指节发白：“我八十一了。再不说，就没机会了。……好。”','He grips his cane white-knuckled. "I\'m eighty-one. If not now, never… All right."','Aperta a bengala até os nós ficarem brancos. «Tenho oitenta e um anos. Se não for agora, nunca… Está bem.»')},
 {t:t('告诉他：“若泽在信里没怪过您。”','Tell him: "José never blamed you in his letters."','Dizer: «O José nunca o culpou nas cartas.»'),fx:()=>{addTrust('colleen',1);S.rep+=1},
  next:()=>c3S('信里其实一个字也没提他。可老人低下头，哭了。','The letters never mention him at all. But the old man bows his head and weeps.','As cartas nem falam dele. Mas o velho baixa a cabeça e chora.')},
 {t:t('冷冷地问：“那您为什么现在才来？”','Ask coldly: "Then why now?"','Perguntar friamente: «Então porquê só agora?»'),fx:()=>{stat('tex',2);S.flags.c3_map=1},
  next:()=>c3S('“因为我怕，”他说，“跟你一样。”他留下一张手画的地图：更衣室在二号仓库后面，北边铁轨那儿的围栏有个缺口。','"Because I was scared," he says. "Same as you." He leaves a hand-drawn map: the locker room is behind Warehouse Two; there\'s a gap in the fence by the north tracks.','«Porque tinha medo», diz. «Como tu.» Deixa um mapa à mão: os balneários ficam atrás do Armazém Dois; há um buraco na vedação junto à linha, a norte.')}]}}},
/* W33 — the license squeeze */
{id:'c3_license',when:c3At(33,3,1),run:()=>{
 if(c3_lic())return {title:t('执照复审通知','License review notice','Aviso de revisão da licença'),meta:t('县酒类管理委员会','County liquor board','Comissão de bebidas do condado'),text:[
  t('挂号信：“接到举报，该店于冰暴期间违规供应酒精。执照下月复审。举报人：匿名。”格蕾丝只说了一句：“又是匿名。”','A certified letter: "A complaint alleges this establishment served alcohol in violation of its license during the ice storm. License review next month. Complainant: anonymous." Grace says only: "Anonymous again."','Carta registada: «Uma denúncia alega que este estabelecimento serviu álcool em violação da licença durante a tempestade. Revisão no próximo mês. Denunciante: anónimo.» A Grace diz só: «Anónimo outra vez.»')],choices:[
  {t:t('请格蕾丝写正式答复','Have Grace write a formal reply','Pedir à Grace uma resposta formal'),req:()=>rel('grace').trust>=3||NEED(t('格蕾丝信任 3','Grace trust 3','Confiança da Grace 3')),fx:()=>{S.flags.c3_lic='grace';addTrust('grace',1)},
   next:()=>c3S('她写了三页，引了七条法规。一周后委员会回信：复审取消。','Three pages, seven statutes. A week later the board writes back: review cancelled.','Três páginas, sete artigos. Uma semana depois a comissão responde: revisão cancelada.')},
  {t:t('请戴尔牧师出面','Ask Pastor Dale to speak','Pedir ao Pastor Dale que fale'),req:()=>rel('dale').trust>=4||NEED(t('戴尔牧师信任 4','Pastor Dale trust 4','Confiança do Pastor Dale 4')),fx:()=>{S.flags.c3_lic='dale';addTrust('megan',1);S.rep+=2},
   next:()=>c3S('牧师只说了一句：“那几天，我和我的会众睡在他的地板上。”复审当场撤销。','The pastor says one sentence: "Those nights, my congregation and I slept on his floor." The review is dropped on the spot.','O pastor diz uma frase: «Nessas noites, eu e a minha congregação dormimos no chão dele.» A revisão é arquivada.')},
  {t:t('自己去委员会解释','Explain it yourself','Explicar tu mesmo'),fx:()=>{const ok=charm()+formalPenalty()>=50;S.flags.c3_lic=ok?'self':'warned';if(!ok)S.rep-=3},
   next:()=>S.flags.c3_lic==='self'?c3S('委员们被你的口音逗笑了一次，然后保留了执照。','Your accent gets one laugh, but the board keeps your license unanimously.','O teu sotaque arranca um riso, mas a comissão mantém a licença por unanimidade.'):c3S('执照保住了，档案里多了一笔警告。','You keep the license, with a warning on file.','Ficas com a licença, com um aviso no processo.',t(`正式场合口音修正 ${formalPenalty()}`,`Formal-setting accent modifier ${formalPenalty()}`,`Modificador de sotaque formal ${formalPenalty()}`))}]};
 return {title:t('警长来访','The sheriff drops by','Visita do xerife'),meta:t('没有执照的店','A shop without a license','Um restaurante sem licença'),text:[
  t('普鲁伊特警长进门：“有人举报你无照卖酒。”你没卖过一滴，可后厨确实有一箱私人藏的波特酒。','Sheriff Pruitt walks in. "Got a report you\'re selling liquor without a license." You haven\'t sold a drop, but there is a private case of port in the kitchen.','O xerife Pruitt entra. «Denunciaram que vendes álcool sem licença.» Não vendeste uma gota, mas há mesmo uma caixa particular de vinho do Porto na cozinha.')],choices:[
  {t:t('打开箱子，说明是私人物品','Open the case and explain','Abrir a caixa e explicar'),fx:()=>{stat('tex',1);addLike('savannah',1)},
   next:()=>c3S('警长看了看标签，什么都没拿。“特拉维斯给我打了三次电话。”他戴上帽子，“我前妻说你人不错。”','The sheriff reads the labels and takes nothing. "Travis called me three times." He puts on his hat. "My ex-wife says you\'re all right."','O xerife lê os rótulos e não leva nada. «O Travis ligou-me três vezes.» Põe o chapéu. «A minha ex-mulher diz que és boa pessoa.»')},
  {t:t('送他一瓶当圣诞礼物','Give him a bottle for Christmas','Oferecer-lhe uma garrafa pelo Natal'),fx:()=>{S.rep-=2;S.flags.c3_bribe=1},
   next:()=>c3S('他收下了。第二天全镇都在传：“葡萄牙人给警长送酒。”','He takes it. By the next day the whole town is saying: "The Portuguese fella\'s buying off the sheriff."','Ele aceita. No dia seguinte a vila inteira diz: «O português anda a comprar o xerife.»')}]}}},
/* W34 — letter 10, the deadline */
{id:'c3_letter10',when:c3At(34,2,0),run:()=>{letter(10);S.flags.c3_key=true;log('找到第 10 封信和十七号柜钥匙','Found letter #10 and the key to locker 17','Encontraste a carta n.º 10 e a chave do cacifo 17');
 return {title:t('若泽的第 10 封信','José\'s letter #10','A carta n.º 10 do José'),meta:t('1998 年的和解','The 1998 settlement','O acordo de 1998'),text:[
 t('第 10 封信在格蕾丝的保险柜里，信封上写着：“如果有人要拆罐头厂，交给我的外甥。”','Letter ten is in Grace\'s safe. On the envelope: "If anyone moves to tear down the cannery, give this to my nephew."','A carta dez está no cofre da Grace. No envelope: «Se alguém quiser deitar abaixo a fábrica, entreguem isto ao meu sobrinho.»'),
 t('“1998 年 6 月，汉克·博伊德把厂边一片没人要的坡地给了我，换我签字：永远不说厂里的事。我签了，在那块地上开了烧烤店，给每个从厂里出来的工人做便宜午饭。我告诉自己这是赎罪。其实是投降。”','"In June 1998 Hank Boyd gave me a useless strip of slope by the plant in exchange for my signature: never speak of what happened there. I signed, opened a grill on that land, and fed cheap lunches to every worker who came out of that plant. I told myself it was penance. It was surrender."','«Em junho de 1998, o Hank Boyd deu-me uma encosta inútil ao pé da fábrica em troca da minha assinatura: nunca falar do que lá se passou. Assinei, abri uma churrasqueira nesse terreno e dei almoços baratos a todos os operários que de lá saíam. Disse a mim mesmo que era penitência. Era rendição.»'),
 t('“报告和协议副本锁在更衣室十七号柜，钥匙挂在烟熏炉后的钉子上。找到了，由你决定让它们见天日，还是跟我一起烂掉。”钉子上果然挂着一把熏黑的铜钥匙，刻着“17”。','"The report and my copy of the agreement are in locker seventeen. The key hangs on the nail behind the smoker. If you find them, you decide: daylight, or rot along with me." On the nail hangs a smoke-black brass key, stamped 17.','«O relatório e o acordo estão no cacifo dezassete. A chave está no prego atrás do fumeiro. Se os encontrares, decides tu: a luz do dia, ou apodrecer comigo.» No prego está uma chave de latão negra de fumo, com o número 17.')],choices:[
 {t:t('问格蕾丝：那份保密协议还有效吗？','Ask Grace: is the gag agreement still binding?','Perguntar à Grace: o acordo de silêncio ainda vale?'),req:()=>rel('grace').trust>=3||NEED(t('格蕾丝信任 3','Grace trust 3','Confiança da Grace 3')),fx:()=>{addTrust('grace',1);S.flags.c3_nda=1},
  next:()=>c3S('“它约束的是若泽，不是你。掩盖违法排污的保密条款，在德州法院站不住。”她顿了顿，“这话你没听市政律师说过。”','"It binds José, not you. And a gag clause covering illegal dumping won\'t stand in a Texas court." A pause. "You didn\'t hear that from the town attorney."','«Obriga o José, não a ti. E uma cláusula que encobre descargas ilegais não se aguenta num tribunal do Texas.» Pausa. «Não ouviste isto da advogada municipal.»')},
 {t:t('把钥匙挂在脖子上','Hang the key around your neck','Pendurar a chave ao pescoço'),fx:()=>{stat('saud',3);stat('tex',2)}}]}}},
{id:'c3_roz2',when:c3At(34,5,2),run:()=>{if(!rel('roz').met)rel('roz').met=true;
 return {title:t('拆除日期','Demolition date','Data da demolição'),meta:t('酒吧后门','Behind the bar','Atrás do bar'),text:[
 t('罗兹在酒吧后门等你：“拆除许可批了。第 37 周星期一，先推更衣室。守夜的十点和两点各巡一圈。大门密码我知道。”','Roz is waiting behind the bar. "Demolition permit came through. Monday of week thirty-seven, the locker room goes first. Watchman does rounds at ten and two. I know the gate code."','A Roz espera-te atrás do bar. «A demolição foi aprovada. Segunda da semana trinta e sete, os balneários vão primeiro. O guarda faz rondas às dez e às duas. Sei o código do portão.»')],choices:[
 {t:t('接过密码','Take the code','Aceitar o código'),req:()=>rel('roz').trust>=4||NEED(t('罗兹信任 4','Roz trust 4','Confiança da Roz 4')),fx:()=>{S.flags.c3_gate=true;addTrust('roz',1)},
  next:()=>c3S('她把四个数字写在你手心，用拇指抹了一下，像要擦掉，又没擦。','She writes four digits on your palm and runs her thumb over them as if to wipe them — and doesn\'t.','Escreve quatro algarismos na tua mão e passa-lhes o polegar como para os apagar — e não apaga.')},
 {t:t('不让她冒险','Don\'t let her take the risk','Não a deixar arriscar'),fx:()=>{addTrust('roz',2);S.flags.c3_gap=1},
  next:()=>c3S('她松了口气，又有点失望：“那至少别走正门。北边铁轨那儿，围栏有个缺口。”','Relieved, a little disappointed: "Then at least not the front gate. By the north tracks there\'s a gap in the fence."','Aliviada e um pouco desiludida: «Então ao menos não vás pelo portão. Junto à linha, a norte, há um buraco na vedação.»')},
 {t:t('问她愿不愿意一起去','Ask her to come with you','Pedir-lhe que venha contigo'),req:()=>rel('roz').like>=4||NEED(t('罗兹好感 4','Roz affection 4','Afeto da Roz 4')),fx:()=>{S.flags.c3_rozCome=1;S.flags.c3_gate=true},
  next:()=>c3S('她犹豫很久：“星期五晚上。我在铁轨边等你，等到十点十分。”','A long hesitation. "Friday night. I\'ll wait by the tracks till ten past ten."','Hesita muito. «Sexta à noite. Espero junto à linha até às dez e dez.»')}]}}},
/* W35 — getting ready */
{id:'c3_prep',when:c3At(35,3,1),run:()=>({title:t('准备','Getting ready','Preparativos'),meta:t('离拆除还有十天','Ten days to demolition','Dez dias para a demolição'),text:[
 t('你在小本子上列清单，写了又划。你只有一个下午。','You write a list in your notebook, cross it out, write it again. You have one afternoon.','Escreves uma lista no caderno, riscas, voltas a escrever. Tens uma tarde.')],choices:[
 {t:t('去农机铺借断线钳和头灯（$40）','Borrow bolt cutters and a headlamp ($40)','Pedir um corta-cadeados e uma lanterna ($40)'),req:MONEY(40),fx:()=>{S.cash-=40;S.flags.c3_prep='tools';addLike('kyle',1)},
  next:()=>c3S('凯尔什么也没问，擦掉钳子上的锈：“老柜子，一剪就开。别剪到手。”','Kyle asks nothing, just wipes the rust off. "Old lockers, one snip. Don\'t snip a finger."','O Kyle não pergunta nada, limpa a ferrugem. «Cacifos velhos, um corte. Não cortes um dedo.»')},
 {t:t('请科琳拿来厂区旧图纸','Get Colleen to bring the old site plans','Pedir à Colleen as plantas da fábrica'),req:()=>rel('colleen').met||NEED(t('认识科琳','Know Colleen','Conhecer a Colleen')),fx:()=>{S.flags.c3_prep='map';addTrust('colleen',1)}},
 {t:t('去贝托的靶场再练一下午','Spend the afternoon at Beto\'s range','Passar a tarde na carreira do Beto'),req:()=>S.course.gun>=1||NEED(t('用枪课 1/3','Shooting 1/3','Tiro 1/3')),fx:()=>{S.flags.c3_prep='range';addTrust('beto',1);stat('tex',2)},
  next:()=>c3S('贝托说：“枪是用来让事情结束的，不是开始的。”他塞给你一支旧手电，“这个更有用。”','Beto says: "A gun\'s for ending things, not starting them." He hands you an old flashlight. "This\'ll do you more good."','O Beto diz: «Uma arma serve para acabar as coisas, não para as começar.» Dá-te uma lanterna velha. «Isto serve-te mais.»')},
 {t:t('什么都不准备，照常营业','Prepare nothing, keep the shop open','Não preparar nada e abrir'),fx:()=>{S.cash+=150;S.flags.c3_prep='none'}}]})},
{id:'c3_lot',when:c3At(35,6,2),run:()=>({title:t('四楼','Fourth floor','Quarto andar'),meta:t('一周之前','A week before','Uma semana antes'),text:[
 t('鲁伊说，妈妈出院了，但以后上楼梯得有人扶。阿尔法马的家在四楼，没有电梯。','Rui says Mom is discharged, but from now on she needs an arm on the stairs. The Alfama flat is on the fourth floor. No lift.','O Rui diz que a mãe teve alta, mas agora precisa de um braço nas escadas. A casa de Alfama é no quarto andar. Sem elevador.')],choices:[
 {t:t('给妈妈打电话，只聊天气','Call Mom, talk only about the weather','Ligar à mãe e falar só do tempo'),fx:()=>{stat('saud',5);S.lusoThisWeek=true},
  next:()=>c3S('挂电话前她说：“你舅舅小时候也怕黑。他总说，怕也要去。”','Before hanging up she says: "Your uncle was scared of the dark as a boy. He always said: scared or not, you go."','Antes de desligar diz: «O teu tio, em pequeno, tinha medo do escuro. Dizia sempre: com medo ou sem ele, vai-se.»')},
 {t:t('跟伊内丝说实话：你要去','Tell Inês the truth: you\'re going','Dizer à Inês que vais'),req:()=>rel('ines').met||NEED(t('认识伊内丝','Know Inês','Conhecer a Inês')),fx:()=>addTrust('ines',2),
  next:()=>c3S('她没劝你：“回来以后，你得请我吃饭。真正的饭，不是沙丁鱼。”','She doesn\'t argue. "When you\'re back, you\'re buying me dinner. A real one. Not sardines."','Não discute. «Quando voltares, pagas-me um jantar. A sério. Sem sardinhas.»')},
 {t:t('去健身房把力气耗光','Burn it off at the gym','Ir gastar as forças ao ginásio'),fx:()=>stat('tex',2)}]})},
/* W36 — Chapter finale: the cannery at night */
{id:'c3_cannery',when:c3At(36,5,2),run:()=>{
 const go=(who,req)=>({t:{beto:t('带贝托去','Take Beto','Levar o Beto'),lucia:t('带露西娅去','Take Lucía','Levar a Lucía'),wade:t('带韦德去','Take Wade','Levar o Wade'),roz:t('带罗兹去','Take Roz','Levar a Roz'),alone:t('一个人去','Go alone','Ir sozinho')}[who],req,fx:()=>{S.flags.canneryWith=who},next:()=>c3_search(who)});
 const need=(id,z,e,p)=>()=>c3_ok(id,4)||NEED(t(z,e,p));
 return {title:t('夜探罐头厂','Night at the cannery','Noite na fábrica'),meta:t('第三章 · 章末','Chapter 3 · Finale','Capítulo 3 · Final'),text:[
  t('星期五夜里，没有月亮。罐头厂的烟囱比天还黑，围栏上挂着新牌子：“孤星砂业 · 私人产业 · 下周一拆除”。','Friday night, no moon. The cannery smokestack is blacker than the sky. A new sign on the fence: "LONE STAR SAND LLC · PRIVATE PROPERTY · DEMOLITION MONDAY."','Sexta à noite, sem lua. A chaminé da fábrica é mais negra do que o céu. Na vedação, uma placa nova: «LONE STAR SAND LLC · PROPRIEDADE PRIVADA · DEMOLIÇÃO NA SEGUNDA.»'),
  S.flags.c3_key?t('铜钥匙贴着胸口。还差一件事：谁跟你去。','The brass key rests on your chest. One thing left: who comes with you.','A chave de latão está no teu peito. Falta uma coisa: quem vem contigo.'):t('你没有钥匙，只有撬棍。还差一件事：谁跟你去。','No key, only a crowbar. One thing left: who comes with you.','Sem chave, só um pé de cabra. Falta uma coisa: quem vem contigo.')],choices:[
  go('beto',need('beto','贝托信任 4','Beto trust 4','Confiança do Beto 4')),
  go('lucia',need('lucia','露西娅信任 4','Lucía trust 4','Confiança da Lucía 4')),
  go('wade',need('wade','韦德信任 4','Wade trust 4','Confiança do Wade 4')),
  go('roz',()=>!!S.flags.c3_rozCome||c3_ok('roz',4)||NEED(t('罗兹信任 4，或约好同去','Roz trust 4, or her promise to come','Confiança da Roz 4, ou a promessa dela'))),
  go('alone')]}}}
);
